import base64
import sys
from pathlib import Path

import freetype


FONT_INDEX = 0
FONT_SIZE = 24
CELL_W = 24
CELL_H = 24
COLS = 94
ENDIAN_BIG = False
FLIP_X = False
FLIP_Y = False
OFFSET_Y = -1

SPECIAL = {
    "EC43": "",
    "EC44": "",
    "EC45": "",
    "EC48": "",
    "EC57": "",
    "EC5C": "",
    "EC5E": "",
    "EC5F": "",
    "EC64": "",
    "EC9F": "",
    "ECA0": "",
    "ECA1": "",
    "ECA2": "",
    "ECA3": "",
    "ECA4": "",
    "ECBF": "",
    "ECC4": "",
}
def parse_table(path):
    items = []
    for line in path.read_text(encoding="utf-16").splitlines():
        line = line.rstrip()
        if not line or "=" not in line:
            continue
        code, text = line.split("=", 1)
        items.append((code.strip().upper(), text))
    return items


def pack(gray):
    out = bytearray()
    for i in range(0, len(gray), 2):
        a = min(15, max(0, (gray[i] + 8) // 17))
        b = min(15, max(0, (gray[i + 1] + 8) // 17))
        out.append((a << 4 | b) if ENDIAN_BIG else (a | (b << 4)))
    return bytes(out)


def flip_tile(gray):
    if not (FLIP_X or FLIP_Y):
        return gray
    out = bytearray(len(gray))
    for y in range(CELL_H):
        sy = CELL_H - 1 - y if FLIP_Y else y
        for x in range(CELL_W):
            sx = CELL_W - 1 - x if FLIP_X else x
            out[y * CELL_W + x] = gray[sy * CELL_W + sx]
    return out


def render(face, ch):
    face.load_char(ch, freetype.FT_LOAD_RENDER | freetype.FT_LOAD_TARGET_NORMAL)
    bmp = face.glyph.bitmap
    tile = bytearray(CELL_W * CELL_H)
    w = int(bmp.width)
    h = int(bmp.rows)
    if w > 0 and h > 0:
        asc = face.size.ascender >> 6
        desc = face.size.descender >> 6
        base_y = (CELL_H - (asc - desc)) // 2 + asc
        x0 = int(face.glyph.bitmap_left)
        if w >= CELL_W:
            x0 = 0
        elif x0 < 0:
            x0 = 0
        elif x0 + w > CELL_W:
            x0 = CELL_W - w
        y0 = base_y - int(face.glyph.bitmap_top) + OFFSET_Y
        pitch = int(bmp.pitch)
        buf = bmp.buffer
        for y in range(h):
            ty = y0 + y
            if 0 <= ty < CELL_H:
                row = ((h - 1 - y) * (-pitch)) if pitch < 0 else y * pitch
                for x in range(w):
                    tx = x0 + x
                    if 0 <= tx < CELL_W:
                        tile[ty * CELL_W + tx] = buf[row + x]
    return pack(flip_tile(tile))


def tile_bytes(face, code, text):
    if code in SPECIAL:
        return base64.b64decode(SPECIAL[code])
    return render(face, text[:1] if text else " ")


def build(items, face):
    tile_size = CELL_W * CELL_H // 2
    cols = COLS
    stride = cols * tile_size // CELL_H
    rows = (len(items) + cols - 1) // cols
    out = bytearray(rows * CELL_H * stride)
    blank = bytes(tile_size)
    for i in range(rows * cols):
        if i < len(items):
            code, text = items[i]
            print(f"{i + 1}/{len(items)} {text}")
            tile = tile_bytes(face, code, text)
        else:
            tile = blank
        gx = i % cols
        gy = i // cols
        for y in range(CELL_H):
            src = y * (CELL_W // 2)
            dst = gy * CELL_H * stride + y * stride + gx * (CELL_W // 2)
            out[dst:dst + CELL_W // 2] = tile[src:src + CELL_W // 2]
    return bytes(out)


def main():
    if len(sys.argv) < 4:
        raise SystemExit("python font_render.py code.tbl font.ttf output.bin")
    table = Path(sys.argv[1])
    font = Path(sys.argv[2])
    out = Path(sys.argv[3])
    items = parse_table(table)
    face = freetype.Face(str(font), index=FONT_INDEX)
    face.set_pixel_sizes(0, FONT_SIZE)
    out.write_bytes(build(items, face))


if __name__ == "__main__":
    main()
